151	// Each sign-in gets its own browser context, so users on one sheet act independently. A context
152	// is closed once the test that opened it has finished: the test runner leaves them open, and a
153	// whole suite of open pages, each still running the app, would exhaust the machine.
154	const opened = new Map<BrowserContext, string>();   // context -> id of the test that opened it
