156	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
157	  let owner = '';
158	  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
159	  for (const [c, t] of opened) {
160	    if (t === owner) continue;
161	    opened.delete(c);
162	    await c.close().catch(() => { /* already gone */ });
163	  }
164	  const context = await browser.newContext();
165	  opened.set(context, owner);
166	  const page = await context.newPage();
167	  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
168	  await page.goto('/');
169	  await page.getByTestId('signin-name').fill(user);
170	  await page.getByTestId('signin-submit').click();
171	  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
172	  await loadSheet(page, sheet);
173	  return page;
174	}
