182	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
183	 *  again is not observable (the current id already reads that), so the screen first loads a
184	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
185	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
186	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
187	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
188	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
189	 *  the screen, are put back if the loads reset them. */
190	export async function refresh(page: Page): Promise<void> {
191	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
192	  const before = new Map<string, number>();
193	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
194	  const retired = page.getByTestId('show-retired');
195	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
196	  const asofWas = await shown(page.getByTestId('sheet-asof'));
197	  const previewWas = await shown(page.getByTestId('sheet-preview'));
198	  await loadSheet(page, sheet + '-reload');
199	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
200	  await loadSheet(page, sheet);
201	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
202	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
203	  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
204	  if (before.size === 0) return;
205	  const back = async () => {
206	    if ((await rows(page).count()) === 0) return false;
207	    for (const [id, n] of before) {
208	      const r = row(page, id);
209	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
210	    }
211	    return true;
212	  };
213	  const deadline = Date.now() + LOAD_WAIT;
214	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
215	}
