765	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
766	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
767	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
768	 *  value it could not have had before). */
769	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
770	  for (const [k, v] of Object.entries(f)) {
771	    const cell = await shown(c.getByTestId(`claim-${k}`));
772	    if (k === 'ref' || k === 'tags') {
773	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
774	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
775	      if (cell !== norm) return false;
776	    } else if (cell !== v) return false;
777	  }
778	  return true;
779	}
