971	/** Assign a review to a user: true once the claim shows the user. */
972	export async function assignReview(page: Page, claimId: string, user: string): Promise<boolean> {
973	  const c = claimRow(page, claimId);
974	  const done = async () => user.trim() !== '' && (await shown(c.getByTestId('claim-review-assigned'))) === user.trim();
975	  const already = await done();
976	  await c.getByTestId('claim-review-user').fill(user);
977	  await c.getByTestId('claim-review-assign').click();
